🐛 Bug
"Cannot instantiate class object" error does not print out the stacktrace or the location of the error. This occurs when attempting to use OrderedDict, among other things.
To Reproduce
@torch.jit.ignore
class MyScriptClass(object):
    def unscriptable(self):
        return "a" + 200


class TestModule(torch.nn.Module):
    def __init__(self):
        super(TestModule, self).__init__()

    def forward(self, x):
        return MyScriptClass()

t = torch.jit.script(TestModule())


Traceback (most recent call last):
File "test/test_jit.py", line 14478, in test_ignore_class
t = torch.jit.script(TestModule())
File "/home/eellison/local/miniconda/envs/ninja/lib/python3.7/site-packages/torch/jit/init.py", line 1159, in script
return torch.jit.torch.jit._recursive.recursive_script(obj)
File "/home/eellison/local/miniconda/envs/ninja/lib/python3.7/site-packages/torch/jit/_recursive.py", line 167, in recursive_script
return copy_to_script_module(mod, overload_stubs + stubs)
File "/home/eellison/local/miniconda/envs/ninja/lib/python3.7/site-packages/torch/jit/_recursive.py", line 89, in copy_to_script_module
torch.jit._create_methods_from_stubs(script_module, stubs)
File "/home/eellison/local/miniconda/envs/ninja/lib/python3.7/site-packages/torch/jit/init.py", line 1367, in _create_methods_from_stubs
self._c._create_methods(self, defs, rcbs, defaults)
File "/home/eellison/local/miniconda/envs/ninja/lib/python3.7/site-packages/torch/jit/annotations.py", line 73, in get_num_params
raise RuntimeError("cannot instantiate class object ({}) inside jit.script".format(py_ast.body[0].name))
RuntimeError: cannot instantiate class object (MyScriptClass) inside jit.script
